2 Samuel 17 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"No plano de Aitofel, quem seria morto no ataque?","o":["Todo o povo que estava com Davi","Joabe e seus homens","Apenas o rei","Os sacerdotes Zadoque e Abiatar"],"c":2,"v":2,"e":"No versículo 2, Aitofel diz que o povo fugiria e ele mataria apenas o rei."},
 {"t":"multipla","p":"A que Husai comparou Davi e seus homens enfurecidos?","o":["A uma ursa que teve os filhotes roubados","A um leão faminto no deserto","A lobos à procura de presa","A uma tempestade no mar"],"c":0,"v":8,"e":"No versículo 8, Husai diz que eles estão enfurecidos como uma ursa no campo que teve seus filhotes roubados."},
 {"t":"multipla","p":"Segundo o capítulo, por que o conselho de Husai foi considerado melhor?","o":["Porque Husai era mais velho que Aitofel","Porque o SENHOR ordenara que o bom conselho de Aitofel fosse dissipado","Porque os anciãos desconfiavam de Aitofel","Porque Absalão tinha medo de atacar à noite"],"c":1,"v":14,"e":"O versículo 14 diz que o SENHOR ordenara que o bom conselho de Aitofel fosse dissipado, para que o mal viesse sobre Absalão."},
 {"t":"multipla","p":"Como a mulher em Bahurim escondeu Jônatas e Aimaás?","o":["Escondeu os dois no telhado, debaixo de linho","Vestiu os dois como servos da casa","Mandou os dois fugirem pelos fundos do pátio","Estendeu uma coberta sobre a boca do poço e espalhou grãos sobre ela"],"c":3,"v":19,"e":"No versículo 19, a mulher estende uma coberta sobre o poço onde os dois desceram e espalha grãos pilados sobre ela."},
 {"t":"multipla","p":"Quem Absalão pôs sobre o exército no lugar de Joabe?","o":["Husai","Abisai","Amasa","Aimaás"],"c":2,"v":25,"e":"O versículo 25 diz que Absalão constituiu Amasa em lugar de Joabe sobre o exército."},
 {"t":"cv","p":"Ao amanhecer, parte do povo de Davi ainda não tinha atravessado o Jordão.","c":false,"v":22,"e":"O versículo 22 diz que, ao amanhecer, não havia um só que não tivesse atravessado o Jordão."},
 {"t":"cv","p":"Quando viu que seu conselho não foi seguido, Aitofel foi para sua cidade, pôs em ordem os seus negócios e se enforcou.","c":true,"v":23,"e":"O versículo 23 conta que Aitofel voltou para casa, organizou seus negócios e se enforcou."},
 {"t":"cv","p":"Os que levaram mantimentos a Davi em Mahanaim disseram que o povo estava faminto, cansado e sedento no deserto.","c":true,"v":29,"e":"No versículo 29 eles dizem que o povo está no deserto, faminto, cansado e sedento."}
]}

2 Samuel 10 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que Davi enviou seus servos a Hanum?","o":["Para consolá-lo pela morte de seu pai","Para cobrar tributo dos amonitas","Para pedir ajuda contra os sírios","Para propor uma aliança de casamento"],"c":0,"v":2,"e":"No versículo 2, Davi envia seus servos para consolar Hanum por causa de seu pai, que tinha usado de bondade para com ele."},
 {"t":"multipla","p":"Do que os príncipes de Amom acusaram os servos de Davi?","o":["De terem roubado o tesouro do rei","De terem vindo espiar a cidade para destruí-la","De terem insultado o falecido rei","De terem trazido presentes falsos"],"c":1,"v":3,"e":"No versículo 3, os príncipes dizem a Hanum que Davi enviou os servos para reconhecer a cidade, espiá-la e destruí-la."},
 {"t":"multipla","p":"O que Hanum fez com os servos de Davi?","o":["Prendeu-os na cidade","Mandou matá-los","Rapou metade da barba deles e cortou suas vestes","Expulsou-os sem deixar que falassem"],"c":2,"v":4,"e":"No versículo 4, Hanum rapa metade da barba dos servos, corta suas vestes até as nádegas e os despede."},
 {"t":"multipla","p":"Onde Davi mandou os servos envergonhados esperarem?","o":["Em Hebrom","Em Belém","Em Gilgal","Em Jericó"],"c":3,"v":5,"e":"No versículo 5, Davi manda que fiquem em Jericó até que a barba lhes cresça novamente."},
 {"t":"multipla","p":"A quem Joabe entregou o restante do povo para enfrentar os filhos de Amom?","o":["A seu irmão Abisai","A Asael","A Benaia","A Amasa"],"c":0,"v":10,"e":"No versículo 10, Joabe entrega o restante do povo a seu irmão Abisai, que forma uma linha contra os filhos de Amom."},
 {"t":"cv","p":"Depois que os sírios fugiram, os filhos de Amom continuaram lutando contra Abisai.","c":false,"v":14,"e":"No versículo 14, ao verem os sírios fugindo, os filhos de Amom também fogem de diante de Abisai e entram na cidade."},
 {"t":"cv","p":"Sobaque, chefe do exército de Hadadezer, foi ferido e morreu na batalha.","c":true,"v":18,"e":"No versículo 18, Davi fere Sobaque, chefe do exército, de tal maneira que ele morre ali."},
 {"t":"cv","p":"Depois da derrota, os sírios continuaram socorrendo os filhos de Amom.","c":false,"v":19,"e":"No versículo 19, os reis servos de Hadadezer fazem paz com Israel, e os sírios passam a temer socorrer os filhos de Amom."}
]}

2 Samuel 2 Â· exercÃ­cios.texto:
