2 Samuel 24 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"A quem Davi mandou percorrer as tribos e fazer o censo do povo?","o":["Gad","Joabe","Araúna","Natã"],"c":1,"v":2,"e":"No versículo 2, o rei manda Joabe, comandante do exército, percorrer as tribos de Dã até Berseba e fazer o censo."},
 {"t":"multipla","p":"O que aconteceu com Davi depois de fazer o censo?","o":["Fez uma grande festa em Jerusalém","Mandou repetir a contagem","O coração dele o recriminou, e ele confessou ao Senhor que tinha pecado","Saiu para guerrear contra Tiro"],"c":2,"v":10,"e":"O versículo 10 diz que o coração de Davi o recriminou e que ele disse ao Senhor: Pequei muito no que fiz."},
 {"t":"multipla","p":"Qual profeta levou a Davi as três opções de castigo?","o":["Natã","Samuel","Elias","Gad"],"c":3,"v":13,"e":"Os versículos 11 a 13 contam que a palavra do Senhor veio ao profeta Gad, vidente de Davi, que foi a Davi com as três opções."},
 {"t":"multipla","p":"Por que Davi preferiu cair nas mãos do Senhor?","o":["Porque muitas são as misericórdias do Senhor","Porque a peste seria a opção mais curta","Porque Joabe o aconselhou assim","Porque não havia inimigos perto"],"c":0,"v":14,"e":"No versículo 14, Davi diz: caiamos nas mãos do Senhor, pois muitas são as suas misericórdias, e acrescenta que não quer cair nas mãos dos homens."},
 {"t":"multipla","p":"Onde estava o anjo do Senhor quando Deus lhe disse: Basta, retire sua mão?","o":["Na fortaleza de Tiro","Na eira de Araúna, o jebuseu","No vale de Gade","Às margens do Jordão"],"c":1,"v":16,"e":"O versículo 16 diz que o anjo do Senhor estava próximo à eira de Araúna, o jebuseu."},
 {"t":"cv","p":"Ao ver o anjo ferindo o povo, Davi disse ao Senhor que o povo é que tinha pecado.","c":false,"v":17,"e":"No versículo 17, Davi diz: Eu é que pequei, e pergunta o que aquelas ovelhas tinham feito."},
 {"t":"cv","p":"Davi foi à eira de Araúna para comprá-la e construir ali um altar ao Senhor, para que a praga cessasse.","c":true,"v":21,"e":"No versículo 21, Davi responde a Araúna que veio comprar a eira para edificar um altar ao Senhor, para que a praga cesse sobre o povo."},
 {"t":"cv","p":"Davi aceitou de graça a eira e os bois que Araúna lhe ofereceu.","c":false,"v":24,"e":"No versículo 24, Davi recusa dizendo que não oferecerá ao Senhor holocaustos que não lhe custem nada, e paga cinquenta siclos de prata."}
]}

