2 Samuel 18 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Davi dividiu o povo em três partes. Quem comandava cada parte?","o":["Joabe, Abisai e Itai","Joabe, Amasa e Itai","Abisai, Ahimaás e Joabe","Joabe, Abisai e Zadoque"],"c":0,"v":2,"e":"No versículo 2, Davi põe um terço do povo sob Joabe, um sob Abisai e um sob Itai, o geteu."},
 {"t":"multipla","p":"Que ordem o rei deu aos capitães a respeito de Absalão?","o":["Que o prendessem vivo e o trouxessem a ele","Que o tratassem com brandura, por amor dele","Que o matassem logo no começo da batalha","Que o deixassem fugir pelo bosque"],"c":1,"v":5,"e":"No versículo 5, o rei diz: \"Tratai com brandura o jovem Absalão, por amor de mim.\""},
 {"t":"multipla","p":"O que aconteceu com Absalão quando passou montado no mulo?","o":["Caiu do mulo dentro de uma cova","Foi cercado junto à porta da cidade","Sua cabeça ficou presa nos ramos de um grande carvalho","Ficou preso em um laço armado no bosque"],"c":2,"v":9,"e":"No versículo 9, a cabeça de Absalão fica presa nos ramos de um carvalho e o mulo segue adiante."},
 {"t":"multipla","p":"Por que o homem que viu Absalão pendurado não o feriu?","o":["Porque Joabe não lhe ofereceu recompensa","Porque Absalão estava armado","Porque era amigo de Absalão","Porque ouviu o rei mandar que guardassem Absalão"],"c":3,"v":12,"e":"No versículo 12, o homem lembra que todos ouviram o rei ordenar: \"Guardem, cada um de vocês, o jovem Absalão.\""},
 {"t":"multipla","p":"O que Joabe fez com Absalão, que ainda estava vivo no carvalho?","o":["Cravou três dardos no coração dele","Cortou os ramos e o levou preso","Mandou avisar o rei antes de agir","Deixou-o pendurado e foi embora"],"c":0,"v":14,"e":"No versículo 14, Joabe toma três dardos e os crava no coração de Absalão."},
 {"t":"cv","p":"Ahimaás correu pelo caminho da planície e ultrapassou o etíope.","c":true,"v":23,"e":"O versículo 23 diz que Ahimaás correu pelo caminho da planície e ultrapassou o etíope."},
 {"t":"cv","p":"Ahimaás contou ao rei que Absalão estava morto.","c":false,"v":29,"e":"No versículo 29, Ahimaás diz que viu um grande alvoroço, mas não sabe o que era."},
 {"t":"cv","p":"Ao ouvir a resposta de Cusi, o rei subiu à sala acima da porta e chorou por Absalão.","c":true,"v":33,"e":"No versículo 33, o rei, profundamente comovido, sobe à sala acima da porta e chora: \"Meu filho Absalão!\""}
